<body>
    <div class="container">
        <h1>🎱 Billiards</h1>
        <div class="instructions">
            <h3>How to Play</h3>
            <ul>
                <li><strong>Aim:</strong> Move your mouse over the white cue ball</li>
                <li><strong>Drag Back:</strong> Click and drag the cue ball backward to aim and set power</li>
                <li><strong>Shoot:</strong> Release to strike the ball (longer drag = harder shot)</li>
                <li><strong>Pockets:</strong> Six pockets: four corners and middle of each long edge</li>
                <li><strong>Reset:</strong> Click "Rack Balls" to return to starting position</li>
            </ul>
        </div>
        <canvas id="gameCanvas"></canvas>
        <div class="controls">
            <button id="rackBtn">🔄 Rack Balls</button>
        </div>
        <div class="stats" id="stats"></div>
    </div>

    <script>
        // Physics simulation engine
        const sim = {
            W: 1000,
            H: 500,
            R: 10,
            friction: 0.85,
            restitution: 0.98,
            pocketRadius: 15,

            balls: [],
            running: true,

            // Pocket positions: 4 corners + 2 middle edges
            pockets: [
                { x: 15, y: 15 },      // top-left
                { x: 985, y: 15 },     // top-right
                { x: 15, y: 485 },     // bottom-left
                { x: 985, y: 485 },    // bottom-right
                { x: 500, y: 15 },     // top-middle
                { x: 500, y: 485 }     // bottom-middle
            ],

            reset: function(balls) {
                this.balls = balls.map(b => ({
                    x: b.x,
                    y: b.y,
                    vx: b.vx || 0,
                    vy: b.vy || 0,
                    cue: b.cue || false,
                    potted: false,
                    originalData: b
                }));
            },

            state: function() {
                return this.balls.map(b => ({
                    x: b.x,
                    y: b.y,
                    vx: b.vx,
                    vy: b.vy,
                    potted: b.potted,
                    cue: b.cue
                }));
            },

            shoot: function(vx, vy) {
                const cueBall = this.balls.find(b => b.cue);
                if (cueBall) {
                    cueBall.vx = vx;
                    cueBall.vy = vy;
                }
            },

            pause: function() {
                this.running = false;
            },

            resume: function() {
                this.running = true;
            },

            step: function(dt) {
                if (!this.running) return;

                // Apply friction
                for (let ball of this.balls) {
                    if (ball.potted) continue;
                    const speed = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);
                    if (speed > 0.1) {
                        const friction = Math.pow(this.friction, dt);
                        ball.vx *= friction;
                        ball.vy *= friction;
                    } else {
                        ball.vx = 0;
                        ball.vy = 0;
                    }
                }

                // Update positions
                for (let ball of this.balls) {
                    if (ball.potted) continue;
                    ball.x += ball.vx * dt;
                    ball.y += ball.vy * dt;
                }

                // Wall collisions
                for (let ball of this.balls) {
                    if (ball.potted) continue;

                    // Cushion bounces
                    if (ball.x - this.R < 0) {
                        ball.x = this.R;
                        ball.vx *= -this.restitution;
                    }
                    if (ball.x + this.R > this.W) {
                        ball.x = this.W - this.R;
                        ball.vx *= -this.restitution;
                    }
                    if (ball.y - this.R < 0) {
                        ball.y = this.R;
                        ball.vy *= -this.restitution;
                    }
                    if (ball.y + this.R > this.H) {
                        ball.y = this.H - this.R;
                        ball.vy *= -this.restitution;
                    }
                }

                // Check pockets
                for (let ball of this.balls) {
                    if (ball.potted) continue;
                    for (let pocket of this.pockets) {
                        const dx = ball.x - pocket.x;
                        const dy = ball.y - pocket.y;
                        const dist = Math.sqrt(dx * dx + dy * dy);
                        if (dist < this.pocketRadius) {
                            ball.potted = true;
                            ball.vx = 0;
                            ball.vy = 0;
                            break;
                        }
                    }
                }

                // Ball-to-ball collisions
                for (let i = 0; i < this.balls.length; i++) {
                    for (let j = i + 1; j < this.balls.length; j++) {
                        const b1 = this.balls[i];
                        const b2 = this.balls[j];
                        if (b1.potted || b2.potted) continue;

                        const dx = b2.x - b1.x;
                        const dy = b2.y - b1.y;
                        const dist = Math.sqrt(dx * dx + dy * dy);
                        const minDist = 2 * this.R;

                        if (dist < minDist) {
                            // Collision detected
                            const nx = dx / dist;
                            const ny = dy / dist;

                            // Relative velocity
                            const dvx = b2.vx - b1.vx;
                            const dvy = b2.vy - b1.vy;
                            const dvn = dvx * nx + dvy * ny;

                            // Don't process if velocities are separating
                            if (dvn >= 0) continue;

                            // For equal mass elastic collision
                            const impulse = -dvn;

                            b1.vx -= impulse * nx;
                            b1.vy -= impulse * ny;
                            b2.vx += impulse * nx;
                            b2.vy += impulse * ny;

                            // Separate balls to prevent overlap
                            const overlap = minDist - dist;
                            const separationX = (overlap / 2) * nx;
                            const separationY = (overlap / 2) * ny;
                            b1.x -= separationX;
                            b1.y -= separationY;
                            b2.x += separationX;
                            b2.y += separationY;
                        }
                    }
                }

                this.render();
            },

            render: function() {
                const canvas = document.getElementById('gameCanvas');
                const ctx = canvas.getContext('2d');

                // Draw table
                ctx.fillStyle = '#0d5c0d';
                ctx.fillRect(0, 0, this.W, this.H);

                // Draw felt texture
                ctx.fillStyle = 'rgba(0, 100, 0, 0.1)';
                for (let i = 0; i < this.W; i += 20) {
                    for (let j = 0; j < this.H; j += 20) {
                        if ((i / 20 + j / 20) % 2 === 0) {
                            ctx.fillRect(i, j, 20, 20);
                        }
                    }
                }

                // Draw cushions (rails)
                ctx.strokeStyle = '#8B4513';
                ctx.lineWidth = 12;
                ctx.strokeRect(6, 6, this.W - 12, this.H - 12);

                // Draw pockets
                ctx.fillStyle = '#1a1a1a';
                for (let pocket of this.pockets) {
                    ctx.beginPath();
                    ctx.arc(pocket.x, pocket.y, this.pocketRadius - 2, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.strokeStyle = '#333';
                    ctx.lineWidth = 2;
                    ctx.stroke();
                }

                // Draw balls
                for (let ball of this.balls) {
                    if (ball.potted) continue;

                    ctx.fillStyle = ball.cue ? '#ffffff' : '#' + Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, '0');
                    ctx.beginPath();
                    ctx.arc(ball.x, ball.y, this.R, 0, Math.PI * 2);
                    ctx.fill();

                    ctx.strokeStyle = '#000';
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    // Simple shading
                    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.beginPath();
                    ctx.arc(ball.x - this.R/3, ball.y - this.R/3, this.R/4, 0, Math.PI * 2);
                    ctx.fill();
                }
            }
        };

        // Canvas setup
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        canvas.width = sim.W;
        canvas.height = sim.H;

        // Ball positions - pool rack formation
        function getRackBalls() {
            const balls = [
                { x: 150, y: sim.H / 2, vx: 0, vy: 0, cue: true }
            ];

            // Triangular rack of 15 balls
            const startX = sim.W - 200;
            const startY = sim.H / 2 - 60;
            const spacing = 2 * sim.R + 2;

            let ballIndex = 0;
            for (let row = 0; row < 5; row++) {
                for (let col = 0; col <= row; col++) {
                    const x = startX + row * spacing * 0.866;
                    const y = startY + (col - row / 2) * spacing;
                    balls.push({ x, y, vx: 0, vy: 0 });
                    ballIndex++;
                }
            }

            return balls;
        }

        // Initialize
        let balls = getRackBalls();
        sim.reset(balls);
        sim.render();

        // Mouse control for shooting
        let dragging = false;
        let dragStartX = 0;
        let dragStartY = 0;
        let dragCurrentX = 0;
        let dragCurrentY = 0;

        canvas.addEventListener('mousedown', (e) => {
            const rect = canvas.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;

            const cueBall = sim.balls.find(b => b.cue);
            if (!cueBall) return;

            const dx = mouseX - cueBall.x;
            const dy = mouseY - cueBall.y;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < sim.R * 2) {
                dragging = true;
                dragStartX = mouseX;
                dragStartY = mouseY;
            }
        });

        canvas.addEventListener('mousemove', (e) => {
            const rect = canvas.getBoundingClientRect();
            dragCurrentX = e.clientX - rect.left;
            dragCurrentY = e.clientY - rect.top;

            if (dragging) {
                sim.render();

                // Draw aim line and power indicator
                const cueBall = sim.balls.find(b => b.cue);
                if (cueBall) {
                    const ctx = canvas.getContext('2d');
                    const dx = dragCurrentX - dragStartX;
                    const dy = dragCurrentY - dragStartY;
                    const dist = Math.sqrt(dx * dx + dy * dy);

                    // Draw cue stick
                    ctx.strokeStyle = 'rgba(139, 69, 19, 0.7)';
                    ctx.lineWidth = 8;
                    ctx.beginPath();
                    ctx.moveTo(dragStartX, dragStartY);
                    ctx.lineTo(dragCurrentX, dragCurrentY);
                    ctx.stroke();

                    // Draw power indicator
                    ctx.fillStyle = 'rgba(255, 200, 0, 0.5)';
                    ctx.fillRect(10, 10, Math.min(dist / 2, 300), 20);
                    ctx.strokeStyle = '#FFD700';
                    ctx.lineWidth = 2;
                    ctx.strokeRect(10, 10, 300, 20);

                    // Draw power text
                    ctx.fillStyle = '#FFD700';
                    ctx.font = 'bold 12px Arial';
                    ctx.fillText('Power: ' + Math.round(dist / 3) + '%', 15, 27);
                }
            }
        });

        canvas.addEventListener('mouseup', (e) => {
            if (!dragging) return;
            dragging = false;

            const dx = dragCurrentX - dragStartX;
            const dy = dragCurrentY - dragStartY;

            // Reverse direction and apply power scaling
            const power = Math.sqrt(dx * dx + dy * dy) / 2;
            const vx = -(dx / Math.max(1, Math.sqrt(dx * dx + dy * dy))) * power;
            const vy = -(dy / Math.max(1, Math.sqrt(dx * dx + dy * dy))) * power;

            sim.shoot(vx, vy);
            sim.render();
        });

        // Rack button
        document.getElementById('rackBtn').addEventListener('click', () => {
            balls = getRackBalls();
            sim.reset(balls);
            dragging = false;
            sim.render();
        });

        // Animation loop
        let lastTime = performance.now();
        function animate(currentTime) {
            const dt = Math.min((currentTime - lastTime) / 1000, 0.016);
            lastTime = currentTime;

            sim.step(dt);

            // Update stats
            const activeBalls = sim.balls.filter(b => !b.potted).length;
            const pottedBalls = sim.balls.filter(b => b.potted).length;
            document.getElementById('stats').textContent = `Active: ${activeBalls} | Potted: ${pottedBalls}`;

            requestAnimationFrame(animate);
        }

        requestAnimationFrame(animate);

        // Expose global sim object
        window.sim = sim;
    </script>
</body>
</html>
